import yaml, sys, json

data = yaml.safe_load(sys.stdin)
exps = data.get('experiments', {})

# Get tau=0.8 seeds (adaptive_ood or adaptive_fromscratch)
tau08_seeds = {}
for prefix in ['adaptive_ood_seed', 'adaptive_fromscratch_seed']:
    for seed in ['42', '123', '456']:
        eid = f'{prefix}{seed}'
        if eid in exps and exps[eid].get('conclusion') == 'success':
            m = exps[eid].get('metrics', {})
            if 'downstream_arc_easy_acc_norm' in m:
                tau08_seeds[eid] = m

# Get uniform seeds
uniform_seeds = {}
for prefix in ['uniform_ood_seed', 'uniform_seed']:
    for seed in ['42', '123', '456']:
        eid = f'{prefix}{seed}'
        if eid in exps and exps[eid].get('conclusion') == 'success':
            m = exps[eid].get('metrics', {})
            if 'downstream_arc_easy_acc_norm' in m:
                uniform_seeds[eid] = m

# Get tau07 seeds
tau07_seeds = {}
for seed in ['42', '123', '456']:
    eid = f'tau07_seed{seed}'
    if eid in exps:
        m = exps[eid].get('metrics', {})
        if 'downstream_arc_easy_acc_norm' in m:
            tau07_seeds[eid] = m

print('=== tau=0.7 ===')
for k, v in tau07_seeds.items():
    print(f'{k}: ARC-E={v.get(\"downstream_arc_easy_acc_norm\")}, ARC-C={v.get(\"downstream_arc_challenge_acc_norm\")}, HS={v.get(\"downstream_hellaswag_acc_norm\")}, PIQA={v.get(\"downstream_piqa_acc_norm\")}, WG={v.get(\"downstream_winogrande_acc\")}')

print()
print('=== tau=0.8 ===')
for k, v in tau08_seeds.items():
    print(f'{k}: ARC-E={v.get(\"downstream_arc_easy_acc_norm\")}, ARC-C={v.get(\"downstream_arc_challenge_acc_norm\")}, HS={v.get(\"downstream_hellaswag_acc_norm\")}, PIQA={v.get(\"downstream_piqa_acc_norm\")}, WG={v.get(\"downstream_winogrande_acc\")}')

print()
print('=== Uniform ===')
for k, v in uniform_seeds.items():
    print(f'{k}: ARC-E={v.get(\"downstream_arc_easy_acc_norm\")}, ARC-C={v.get(\"downstream_arc_challenge_acc_norm\")}, HS={v.get(\"downstream_hellaswag_acc_norm\")}, PIQA={v.get(\"downstream_piqa_acc_norm\")}, WG={v.get(\"downstream_winogrande_acc\")}')

# Also check adaptive_fromscratch_seed42
if 'adaptive_fromscratch_seed42' in exps:
    e = exps['adaptive_fromscratch_seed42']
    print(f'\\nadaptive_fromscratch_seed42: status={e.get(\"status\")}, conclusion={e.get(\"conclusion\")}')
" 2>/dev/null
